              }}>
              <Fragment ref={fragmentRef}>
                <ScrollIntoViewCaseSimple />
              </Fragment>
            </div>
          )}
          {exampleType === 'multiple' && (
            <Fragment>
              <div
                style={{
                  height: '50vh',
                  overflowY: 'auto',
                  border: '1px solid black',
                  marginBottom: '1rem',
