def get_optimus_optimize_ctx(config, nopython, inductor_compile_mode):
    if config == "vertical_opt":
        optimus_inductor_config = {
            "pre_grad_fusion_options": {
                "normalization_pass": {},
                "merge_splits_pass": {},
                "split_cat_pass": {},
                "unbind_stack_pass": {},
