### Input:
arr = [1, 2, 3, 4, 5, 6, 7, 8]

### Response:
def binarySearch(arr, element):
    start = 0;
    end = len(arr) - 1

    while start <= end:
        mid = (start + end) // 2
        if arr[mid] == element:
            return mid
        elif arr[mid] < element:
            start = mid + 1
        else:
            end = mid - 1 
    return -1

