### Instruction:
Sort the following array in ascending order using insertion sort in JavaScript.

### Input:
[7, 2, 5, 3, 8]

### Response:
function insertionSort(arr) {
  for (let i = 1; i < arr.length; i++) {
    let currentVal = arr[i];
    for (var j = i - 1; j >= 0 && arr[j] > currentVal; j--) {
      arr[j + 1] = arr[j];
    }
    arr[j + 1] = currentVal;
  }
  return arr;
}

// Test
