### Instruction:
Create a function that encodes a message into a Vigenere cipher

### Response:
def vigenere_encode(message, key):
    encoded_message = ""
    key_index = 0
    for character in message:
        if character.isalpha():
            shift_amount = ord(key[key_index]) % 26
            key_index += 1
            if key_index == len(key):
                key_index = 0  
            shifted_char_code = ord(character) + shift_amount
            if shifted_char_code > ord('z'):
                shifted_char_code -= 26
            encoded_message += chr(shifted_char_code)
        else:
            encoded_message += character
    return encoded_message

