public List<String> removeDuplicates(List<String> inputList) { 

   // Create a new HashSet 
   HashSet<String> hs = new HashSet<>(); 

   // Add the contents of inputList to the HashSet hs 
   // HashSet does not allow duplicates 
   hs.addAll(inputList); 

   // Clear inputList 
